// API Configuration
// Use local server for development, remote server for production
export const API_BASE_URL = import.meta.env.DEV 
  ? 'http://localhost:5000' 
  : 'https://talenttrek-api.vercel.app';

// API Endpoints
export const API_ENDPOINTS = {
  // Authentication
  LOGIN: `${API_BASE_URL}/api/login`,
  SIGNUP: `${API_BASE_URL}/api/signup`,
  PROTECTED: `${API_BASE_URL}/api/protected`,

  // Jobs
  JOBS: `${API_BASE_URL}/api/jobs`,
  POST_JOB: `${API_BASE_URL}/api/jobs`,
  SEED_JOBS: `${API_BASE_URL}/api/jobs/seed`,
  MY_JOBS: `${API_BASE_URL}/api/jobs/my/jobs`,
  JOB_APPLICATIONS: (jobId) => `${API_BASE_URL}/api/jobs/${jobId}/applications`,

  // File Uploads
  UPLOAD_LOGO: `${API_BASE_URL}/api/upload-logo`,
  UPLOAD_RESUME: `${API_BASE_URL}/api/upload/resume`,

  // Profile Management
  PROFILE: `${API_BASE_URL}/api/profile`,
  PROFILE_BASIC: `${API_BASE_URL}/api/profile/basic`,
  PROFILE_PICTURE: `${API_BASE_URL}/api/profile/picture`,
  PROFILE_JOBSEEKER: `${API_BASE_URL}/api/profile/jobseeker`,
  PROFILE_RECRUITER: `${API_BASE_URL}/api/profile/recruiter`,
  PROFILE_COMPANY_LOGO: `${API_BASE_URL}/api/profile/company-logo`,

  // User-specific endpoints (protected)
  USER_PROFILE: `${API_BASE_URL}/api/user/profile`,
  USER_DASHBOARD: `${API_BASE_URL}/api/user/dashboard`,
  USER_APPLICATIONS: `${API_BASE_URL}/api/user/applications`,
  USER_JOBS: `${API_BASE_URL}/api/user/jobs`,

  // Experience Management
  PROFILE_EXPERIENCE: `${API_BASE_URL}/api/profile/experience`,
  PROFILE_EXPERIENCE_BY_ID: (experienceId) => `${API_BASE_URL}/api/profile/experience/${experienceId}`,

  // Education Management
  PROFILE_EDUCATION: `${API_BASE_URL}/api/profile/education`,

  // Applications
  APPLY: `${API_BASE_URL}/api/apply`,
  MY_APPLICATIONS: `${API_BASE_URL}/api/apply/my-applications`,
  CHECK_APPLICATION: (jobId) => `${API_BASE_URL}/api/apply/check/${jobId}`,

  // Job Recommendations
  JOB_RECOMMENDATIONS: `${API_BASE_URL}/api/job-recommendations`,

  // Utilities
  SEED_JOBS: `${API_BASE_URL}/api/jobs/seed`,
  HEALTH_CHECK: `${API_BASE_URL}/api/health`,
};

export default API_BASE_URL;

import React, { createContext, useContext, useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { API_ENDPOINTS } from '../config/api';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if user is logged in on app start
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');
    
    if (token && userData) {
      try {
        setUser(JSON.parse(userData));
      } catch (error) {
        console.error('Error parsing user data:', error);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }
    setLoading(false);
  }, []);

  const login = async (email, password) => {
    try {
      const res = await fetch(API_ENDPOINTS.LOGIN, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (data.success) {
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        setUser(data.user);
        toast.success('Login successful!');
        return { success: true };
      } else {
        toast.error(data.message || 'Invalid credentials');
        return { success: false, error: data.message };
      }
    } catch (error) {
      toast.error('Login failed. Please try again.');
      return { success: false, error: error.message };
    }
  };

  const signup = async (name, email, password, role) => {
    try {
      const res = await fetch(API_ENDPOINTS.SIGNUP, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, email, password, role }),
      });
      const data = await res.json();
      if (data.success) {
        // Auto-login after signup
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        setUser(data.user);
        toast.success('Account created successfully!');
        return { success: true };
      } else {
        toast.error(data.message || 'Signup failed');
        return { success: false, error: data.message };
      }
    } catch (error) {
      toast.error('Signup failed. Please try again.');
      return { success: false, error: error.message };
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    toast.success('Logged out successfully');
  };

  const value = {
    user,
    loading,
    login,
    signup,
    logout,
    isAuthenticated: !!user
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  IoBriefcaseOutline, 
  IoPersonOutline, 
  IoLogOutOutline, 
  IoChevronDownOutline,
  IoPeopleOutline,
  IoStatsChartOutline,
  IoAddOutline,
  IoNotificationsOutline
} from "react-icons/io5";
import { useAuth } from '../context/AuthContext';
import './Navbar.css';

const Navbar = ({ isSimplified = false }) => {
  const { user, logout, isAuthenticated } = useAuth();
  const [showDropdown, setShowDropdown] = useState(false);
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    setShowDropdown(false);
  };

  return (
    <nav className={`navbar ${isSimplified ? 'navbar-simplified' : ''}`}>
       
      <div className="navbar-left">
        <Link to="/" className="navbar-brand">
          <IoBriefcaseOutline className="navbar-logo" />
          <span className="brand-name">TalentTrek</span>
        </Link>
      </div>

      {/* Conditionally render navbar center - hide for simplified layout */}
      {!isSimplified && (
        <div className="navbar-center">
          {/* Show different navigation based on user role */}
          {isAuthenticated && user?.role === 'recruiter' ? (
            // Enhanced Recruiter Navigation
            <>
              <Link to="/dashboard" className="navbar-link-enhanced">
                <IoBriefcaseOutline className="navbar-link-icon" />
                Dashboard
              </Link>
              <Link to="/post-job" className="navbar-link-enhanced">
                <IoAddOutline className="navbar-link-icon" />
                Post Jobs
              </Link>
              <Link to="/candidates" className="navbar-link-enhanced">
                <IoPeopleOutline className="navbar-link-icon" />
                Candidates
              </Link>
              <Link to="/analytics" className="navbar-link-enhanced">
                <IoStatsChartOutline className="navbar-link-icon" />
                Analytics
              </Link>
            </>
          ) : (
            // Job Seeker Navigation (default)
            <>
              <Link to="/">Home</Link>
              <Link to="/browse-jobs">Browse Jobs</Link>
              <Link to="/companies">Companies</Link>
              <a href="#">Career Resources</a>
            </>
          )}
        </div>
      )}

       
      <div className="navbar-right">
        {isAuthenticated ? (
          <div className="navbar-right-authenticated">
            {/* Enhanced features for recruiters */}
            {user?.role === 'recruiter' && (
              <>
                {/* Notifications */}
                <button className="navbar-notification-btn">
                  <IoNotificationsOutline className="notification-icon" />
                  <span className="notification-badge">3</span>
                </button>
              </>
            )}
            
            <div className="user-menu">
              <button 
                className="user-button"
                onClick={() => setShowDropdown(!showDropdown)}
              >
                <IoPersonOutline className="user-icon" />
                <span className="user-name">{user?.name || 'User'}</span>
                <IoChevronDownOutline className="dropdown-icon" />
              </button>
              
              {showDropdown && (
                <div className="user-dropdown">
                  <div className="dropdown-header">
                    <p className="user-email">{user?.email}</p>
                    <p className="user-role">{user?.role}</p>
                  </div>
                  <div className="dropdown-divider"></div>
                  <Link to="/profile" className="dropdown-item">
                    <IoPersonOutline />
                    Profile
                  </Link>
                  <Link to="/dashboard" className="dropdown-item">
                    <IoBriefcaseOutline />
                    Dashboard
                  </Link>
                  {user?.role === 'recruiter' && (
                    <Link to="/post-job" className="dropdown-item">
                      <IoBriefcaseOutline />
                      Post a Job
                    </Link>
                  )}
                  <button onClick={handleLogout} className="dropdown-item logout">
                    <IoLogOutOutline />
                    Sign Out
                  </button>
                </div>
              )}
            </div>
          </div>
        ) : (
          <>
            <Link to="/login" className="sign-in">Sign In</Link>
            <Link to="/signup" className="post-job">Sign Up</Link>
          </>
        )}
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  IoDocumentTextOutline, 
  IoBookmarkOutline, 
  IoChatbubbleOutline, 
  IoCalendarOutline,
  IoTrendingUpOutline,
  IoSearchOutline,
  IoNotificationsOutline,
  IoCloudUploadOutline,
  IoEllipsisVerticalOutline,
  IoCalendarClearOutline,
  IoPersonOutline,
  IoHomeOutline,
  IoBriefcaseOutline
} from 'react-icons/io5';
import { API_ENDPOINTS } from '../../config/api';
import { makeAuthenticatedRequest, getCurrentUser } from '../../utils/apiUtils';
import Calendar from '../../components/Calendar';
import './Dashboard.css';

const Dashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('All Status');
  const [typeFilter, setTypeFilter] = useState('All Types');
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);
  const [realApplications, setRealApplications] = useState([]);

  useEffect(() => {
    loadDashboardData();
    loadApplicationsData();
  }, []);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showProfileDropdown && !event.target.closest('.profile-menu')) {
        setShowProfileDropdown(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showProfileDropdown]);

  const loadDashboardData = async () => {
    try {
      const currentUser = getCurrentUser();
      if (!currentUser || !currentUser.userId) {
        console.error('No authenticated user found');
        setLoading(false);
        return;
      }

      // Load user-specific dashboard data
      const data = await makeAuthenticatedRequest(API_ENDPOINTS.USER_DASHBOARD);
      if (data.success) {
        setDashboardData(data.data);
        console.log('Dashboard data loaded:', data.data);
      } else {
        console.error('Failed to load dashboard data:', data.message);
      }
    } catch (error) {
      console.error('Error loading dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  // Load applications data
  const loadApplicationsData = async () => {
    try {
      const data = await makeAuthenticatedRequest(API_ENDPOINTS.USER_APPLICATIONS);
      if (data.success) {
        setRealApplications(data.applications);
        console.log('Applications loaded:', data.applications);
      } else {
        console.error('Failed to load applications:', data.message);
      }
    } catch (error) {
      console.error('Error loading applications:', error);
    }
  };

  // Statistics data from backend or fallback
  const getStats = () => {
    const statistics = dashboardData?.statistics;
    return [
      {
        title: 'Job Applications',
        subtitle: 'vs last month',
        value: statistics?.totalApplications?.toString() || '0',
        change: '+30%',
        changeType: 'increase',
        icon: <IoDocumentTextOutline />,
        bgColor: 'bg-blue-50',
        iconBg: 'bg-blue-100',
        iconColor: 'text-blue-600'
      },
      {
        title: 'Upcoming Interviews',
        subtitle: 'vs last month',
        value: statistics?.upcomingInterviews?.toString() || '0',
        change: '+40%',
        changeType: 'increase',
        icon: <IoCalendarOutline />,
        bgColor: 'bg-orange-50',
        iconBg: 'bg-orange-100',
        iconColor: 'text-orange-600'
      },
      {
        title: 'Shortlisted',
        subtitle: 'vs last month',
        value: statistics?.shortlisted?.toString() || '0',
        change: '+30%',
        changeType: 'increase',
        icon: <IoBookmarkOutline />,
        bgColor: 'bg-green-50',
        iconBg: 'bg-green-100',
        iconColor: 'text-green-600'
      },
      {
        title: 'Job Offers Received',
        subtitle: 'vs last month',
        value: statistics?.jobOffersReceived?.toString() || '0',
        change: '+30%',
        changeType: 'increase',
        icon: <IoTrendingUpOutline />,
        bgColor: 'bg-purple-50',
        iconBg: 'bg-purple-100',
        iconColor: 'text-purple-600'
      },
      {
        title: 'Application Review',
        subtitle: 'vs last month',
        value: statistics?.applicationReview?.toString() || '0',
        change: '+15%',
        changeType: 'increase',
        icon: <IoDocumentTextOutline />,
        bgColor: 'bg-yellow-50',
        iconBg: 'bg-yellow-100',
        iconColor: 'text-yellow-600'
      }
    ];
  };

  // Sidebar navigation items with real counts
  const getSidebarItems = () => {
    const statistics = dashboardData?.statistics;
    return [
      {
        id: 'dashboard',
        title: 'Dashboard',
        icon: <IoHomeOutline />,
        active: true
      },
      {
        id: 'applications',
        title: 'Applications',
        icon: <IoDocumentTextOutline />,
        count: statistics?.totalApplications || realApplications.length
      },
      {
        id: 'saved-jobs',
        title: 'Saved Jobs',
        icon: <IoBookmarkOutline />,
        count: 0 // TODO: Implement saved jobs
      },
      {
        id: 'messages',
        title: 'Messages',
        icon: <IoChatbubbleOutline />,
        count: 0 // TODO: Implement messages
      },
      {
        id: 'schedule',
        title: 'My Schedule',
        icon: <IoCalendarOutline />,
        count: statistics?.upcomingInterviews || 0
      }
    ];
  };

  // No mock applications - only use real data from backend

  // Filter applications based on selected filters - only real applications
  const getFilteredApplications = () => {
    return realApplications.filter(app => {
      const statusMatch = statusFilter === 'All Status' || app.stage === statusFilter;
      const typeMatch = typeFilter === 'All Types' || app.type === typeFilter;
      return statusMatch && typeMatch;
    });
  };

  // Get applications for dashboard (first 4) - only real applications
  const applications = realApplications.slice(0, 4);

  // Handle logout
  const handleLogout = () => {
    logout();
    setShowProfileDropdown(false);
    navigate('/');
  };

  // Handle view profile
  const handleViewProfile = () => {
    setShowProfileDropdown(false);
    navigate('/profile');
  };

  // Handle logo click to navigate to home page
  const handleLogoClick = () => {
    navigate('/');
  };

  // Function to render content based on active tab
  const renderContent = () => {
    switch(activeTab) {
      case 'dashboard':
        return (
          <>
            {/* Welcome Section */}
            <div className="px-6 py-6 bg-white mt-20">
              <div className="mb-6">
                <h2 className="text-2xl font-semibold text-gray-900 mb-2">
                  Welcome back, {user?.name || 'Mayank'}!
                </h2>
                <p className="text-gray-600">You have 32 upcoming interviews this week</p>
              </div>

              {/* Statistics Cards */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-8">
                {getStats().map((stat, index) => (
                  <div key={index} className={`${stat.bgColor} rounded-xl p-4 border border-gray-100`}>
                    <div className="flex items-center justify-between mb-3">
                      <div className={`w-10 h-10 ${stat.iconBg} rounded-lg flex items-center justify-center`}>
                        <span className={`${stat.iconColor} text-lg`}>
                          {stat.icon}
                        </span>
                      </div>
                      <span className="text-green-600 text-sm font-medium">{stat.change}</span>
                    </div>
                    <div className="space-y-1">
                      <div className="text-2xl font-bold text-gray-900">{stat.value}</div>
                      <div className="text-sm text-gray-600">{stat.title}</div>
                      <div className="text-xs text-gray-500">{stat.subtitle}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Applications Table */}
            <div className="flex-1 px-6 pb-6">
              <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between">
                  <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                    <IoDocumentTextOutline />
                    My Applications
                  </h3>
                  <button className="text-blue-600 hover:text-blue-700 text-sm font-medium">
                    View All
                  </button>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">No</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Company Name</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Job Title</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Interview</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Type</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Stage</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {applications.length > 0 ? applications.map((app, index) => (
                        <tr key={app.id} className="hover:bg-gray-50">
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {index + 1}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                            {app.company}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {app.jobTitle}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {app.interview ? (
                              <div className="flex items-center gap-2">
                                <IoCalendarClearOutline className="text-purple-600" />
                                {app.interview}
                              </div>
                            ) : (
                              <span className="text-gray-400">-</span>
                            )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                              {app.type}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${app.stageColor}`}>
                              {app.stage}
                            </span>
                          </td>
                        </tr>
                      )) : (
                        <tr>
                          <td colSpan="6" className="px-6 py-8 text-center">
                            <div className="flex flex-col items-center justify-center">
                              <IoDocumentTextOutline className="text-3xl text-gray-300 mb-3" />
                              <p className="text-gray-500">No applications yet</p>
                            </div>
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </>
        );

      case 'applications':
        return (
          <div className="px-6 py-6 mt-20">
            <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
              <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-semibold text-gray-900 flex items-center gap-2">
                    <IoDocumentTextOutline />
                    All Applications
                  </h2>
                  <p className="text-sm text-gray-500 mt-1">
                    Showing {getFilteredApplications().length} of {realApplications.length} applications
                  </p>
                </div>
                <div className="flex gap-2">
                  <select 
                    className="border border-gray-300 rounded-lg px-3 py-2 text-sm"
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                  >
                    <option>All Status</option>
                    <option>Applied</option>
                    <option>Interview</option>
                    <option>Under Review</option>
                    <option>Rejected</option>
                  </select>
                  <select 
                    className="border border-gray-300 rounded-lg px-3 py-2 text-sm"
                    value={typeFilter}
                    onChange={(e) => setTypeFilter(e.target.value)}
                  >
                    <option>All Types</option>
                    <option>Full-time</option>
                    <option>Part-time</option>
                    <option>Remote</option>
                    <option>Contract</option>
                  </select>
                  {(statusFilter !== 'All Status' || typeFilter !== 'All Types') && (
                    <button 
                      onClick={() => {
                        setStatusFilter('All Status');
                        setTypeFilter('All Types');
                      }}
                      className="px-3 py-2 text-sm text-gray-600 hover:text-gray-800 border border-gray-300 rounded-lg hover:bg-gray-50"
                    >
                      Clear Filters
                    </button>
                  )}
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">No</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Company Name</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Job Title</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Interview</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Type</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Stage</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Applied Date</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"></th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {/* Show filtered applications or empty state */}
                    {getFilteredApplications().length > 0 ? getFilteredApplications().map((app, index) => (
                      <tr key={app.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {index + 1}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {app.company}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {app.jobTitle}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {app.interview ? (
                            <div className="flex items-center gap-2">
                              <IoCalendarClearOutline className="text-purple-600" />
